// QualityProfile defines model for QualityProfile.
type QualityProfile struct {
	// FormatSelector yt-dlp -f style format selector; Creatorr passes it to the domain handler as --format
	FormatSelector string `json:"format_selector"`
	Id             int64  `json:"id"`

	// MaturityRedownloadHours Hours after upload_date for one blind media maturity pass (0 = off for all series on this profile).
	MaturityRedownloadHours int `json:"maturity_redownload_hours"`

	// MaturitySidecarHours Hours after upload_date for one NFO/thumb/subs refresh (0 = off). UI edits this as days. Does not rewrite info.json.
	MaturitySidecarHours int    `json:"maturity_sidecar_hours"`
	Name                 string `json:"name"`

	// SponsorblockInfoCards When reencode_cut is on and remove is non-empty, insert hard-cut info cards at each skip. Rejected if set without reencode_cut.
	SponsorblockInfoCards bool `json:"sponsorblock_info_cards"`

	// SponsorblockMark SponsorBlock categories to embed as extra MKV chapters (explicit list; empty = off). Must be disjoint from sponsorblock_remove.
	SponsorblockMark []string `json:"sponsorblock_mark"`

	// SponsorblockReencodeCut When remove is non-empty, re-encode keep segments for accurate cut timestamps (bitrate-matched H.264; AV1/VP9/VP8 sources get 1.5× video bitrate). Off = stream-copy keyframe snap.
	SponsorblockReencodeCut bool `json:"sponsorblock_reencode_cut"`

	// SponsorblockRemove SponsorBlock categories to cut/skip (explicit list; empty = off). Must be disjoint from sponsorblock_mark.
	SponsorblockRemove []string `json:"sponsorblock_remove"`

	// VerifyMedia When true, after archive pack enqueue system integrity_check_initial (null-decode + checksums when File integrity on). With maturity_redownload_hours > 0, young first packs skip verify until the maturity re-download (or when maturity will never run). Default false.
	VerifyMedia bool `json:"verify_media"`
}

